import { Text } from '@react-three/drei';
const stations = [
  { id: 'place', number: '01 / PLACE', title: '配置を整える', body: 'HierarchyでEntityを選びます。\nInspectorで位置・回転・大きさを調整します。', x: -2.05, z: -2.6, yaw: 0.3 },
  { id: 'material', number: '02 / MATERIAL', title: '質感を比べる', body: '色とRoughnessを変えます。\n立体見本を見ながら、光の反射を比べます。', x: 0, z: -3, yaw: 0 },
  { id: 'play', number: '03 / PLAY', title: '歩いて確かめる', body: 'Playでワールドを確認します。\n文字が読める距離と通路の広さを確かめます。', x: 2.05, z: -2.6, yaw: -0.3 }
];
function InfoCard({ number, title, body, x, z, yaw }) {
  return <group name='InfoCard' position={[x, 1.55, z]} rotation={[0, yaw, 0]}>
    <mesh name='Backing'><boxGeometry args={[1.9, 1.5, 0.05]} /><meshBasicMaterial color='#182939' /></mesh>
    <mesh name='Accent' position={[-0.89, 0, 0.032]}><boxGeometry args={[0.025, 1.3, 0.012]} /><meshBasicMaterial color='#62d6c3' /></mesh>
    <Text name='Section' position={[-0.77, 0.57, 0.04]} fontSize={0.055} maxWidth={1.54} anchorX='left' anchorY='top' color='#88e0d0' letterSpacing={0.06}>{number}</Text>
    <Text name='Heading' position={[-0.77, 0.37, 0.04]} fontSize={0.13} maxWidth={1.54} anchorX='left' anchorY='top' fontWeight={700} color='#f3f8fc'>{title}</Text>
    <Text name='Body' position={[-0.77, 0.08, 0.04]} fontSize={0.08} maxWidth={1.54} anchorX='left' anchorY='top' textAlign='left' lineHeight={1.45} color='#d8e5ee'>{body}</Text>
  </group>;
}
export default function World() {
  return <group name='LearningStations'>
    {stations.map(station => <InfoCard key={station.id} number={station.number} title={station.title} body={station.body} x={station.x} z={station.z} yaw={station.yaw} />)}
  </group>;
}
